sql:
SELECT notes 
FROM event 
WHERE event_name = 'fundraising' AND event_date = '2019-09-14';

SELECT SUM(e.cost) AS total_cost
FROM expense e
WHERE e.expense_description LIKE '%Pizza%';

SELECT event_name
FROM event
WHERE type = 'Game' AND status = 'Closed' AND event_date BETWEEN '2019-03-15' AND '2020-03-20';

SELECT COUNT(*) 
FROM Player_Attributes 
WHERE preferred_foot = 'left' AND attacking_work_rate = 'low';

SELECT player_name
FROM Player
WHERE height = (SELECT MAX(height) FROM Player);

SELECT COUNT(*) 
FROM users 
WHERE LastAccessDate > '2014-09-01';

SELECT 
    (SELECT SUM(ViewCount) FROM posts WHERE OwnerDisplayName = 'Mornington') -
    (SELECT SUM(ViewCount) FROM posts WHERE OwnerDisplayName = 'Amos') AS ViewCountDifference;
